DROP TABLE IF EXISTS `account_plan_entries_entry`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `account_plan_entries_entry` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('initial','reinforcement','annulment','redistribuition_reinforcement','redistribuition_annulment','initial_allocation','entry_bills_to_pay','entry_bank_out','entry_regularization') DEFAULT NULL,
  `operator` enum('debit','credit') NOT NULL,
  `allocation` double NOT NULL,
  `last_final_allocation` double NOT NULL,
  `operation_date` datetime DEFAULT NULL,
  `posting_month` int NOT NULL,
  `posting_date` timestamp NOT NULL,
  `entry_id` int unsigned DEFAULT NULL,
  `target_entrie_entry_id` int unsigned DEFAULT NULL,
  `account_plan_year_id` int unsigned DEFAULT NULL,
  `state` int NOT NULL DEFAULT '1',
  `created_by` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_by` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `compliance_status` varchar(30) DEFAULT 'Pending_conformaconce',
  `description_moviment` text,
  `description_compliance` text,
  `approvedBy` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_entry_id` (`entry_id`),
  KEY `fk_account_plan_year_id` (`account_plan_year_id`),
  KEY `fk_target_entrie_entry_id` (`target_entrie_entry_id`),
  KEY `fk_approved_by` (`approvedBy`),
  CONSTRAINT `fk_account_plan_year_id` FOREIGN KEY (`account_plan_year_id`) REFERENCES `account_plan_years` (`id`),
  CONSTRAINT `fk_approved_by` FOREIGN KEY (`approvedBy`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_target_entrie_entry_id` FOREIGN KEY (`target_entrie_entry_id`) REFERENCES `account_plan_entries_entry` (`id`),
  CONSTRAINT `account_plan_entries_entry_chk_1` CHECK ((`type` in (_utf8mb4'initial',_utf8mb4'reinforcement',_utf8mb4'annulment',_utf8mb4'redistribuition_reinforcement',_utf8mb4'redistribuition_annulment',_utf8mb4'initial_allocation',_utf8mb4'entry_bills_to_pay',_utf8mb4'entry_bank_out',_utf8mb4'entry_regularization'))),
  CONSTRAINT `account_plan_entries_entry_chk_2` CHECK ((`operator` in (_utf8mb4'debit',_utf8mb4'credit')))
